function vnParts(d) {
  const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short' });
  const parts = fmt.formatToParts(d); const get = (t) => parts.find(p => p.type === t).value;
  return { y: get('year'), m: get('month'), d: get('day'), weekday: get('weekday') };
}
function uuidv4() { return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r=Math.random()*16|0; return (c==='x'?r:(r&3|8)).toString(16); }); }
const now=new Date(); const todayVN=vnParts(now); const weekdayMap={Mon:2,Tue:3,Wed:4,Thu:5,Fri:6,Sat:7,Sun:0};
const reportDay=weekdayMap[todayVN.weekday]; const isSaturday=todayVN.weekday==='Sat'; const isSunday=todayVN.weekday==='Sun';
const yesterdayDate=new Date(now.getTime()-86400000); const yVN=vnParts(yesterdayDate); const reportDate=yVN.y+'-'+yVN.m+'-'+yVN.d;
const dayNames={0:'Chủ Nhật',2:'Thứ Hai',3:'Thứ Ba',4:'Thứ Tư',5:'Thứ Năm',6:'Thứ Sáu',7:'Thứ Bảy'};
const focusTitles={2:'MARKETING DAY 1 ALERT',3:'MARKETING DAY 2 & BRAND ALERT',4:'EXECUTIVE EDUCATION ALERT',5:'DATA SCHOOL ALERT',6:'TM AI, FLEXIBLE COMBO & B2B TRAINING ALERT'};
const weekKey=todayVN.y+'-W'+String(Math.ceil((Number(todayVN.d)+6)/7)).padStart(2,'0');
return [{json:{run_id:uuidv4(),report_date:reportDate,report_day:reportDay,is_saturday:isSaturday,is_sunday:isSunday,report_mode:isSunday?'sunday':(isSaturday?'weekly':'daily'),weekday_label:dayNames[reportDay]||'',focus_title:focusTitles[reportDay]||'',week_key:weekKey}}];

const cfg=$('Config').first().json; const rd=$('Resolve Day').first().json;
function rows(name){ return $(name).all().map(i=>i.json); }
function countFlags(r){ return ['flag_lead_drop','flag_deal_drop','flag_no_lead','flag_pending','flag_stale_open'].reduce((n,k)=>n+(r[k]?1:0),0); }
let payload={run_id:rd.run_id,report_date:rd.report_date,weekday_label:rd.weekday_label,focus_title:rd.focus_title,report_mode:rd.report_mode,is_saturday:rd.is_saturday,is_sunday:false};
if(rd.is_saturday){
  const courses=rows('Q7 Weekly Performance'); const content=rows('Q7 Content Performance'); const warningRaw=rows('Q7 Warning Snapshot'); const healthRows=rows('Q7 Weekly Data Health');
  const warnings=warningRaw.filter(r=>countFlags(r)>0).sort((a,b)=>countFlags(b)-countFlags(a)).slice(0,cfg.limits.max_warning_rows);
  const tracked=content.filter(r=>String(r.utm_content||'').trim() && r.utm_content!=='(not set)');
  const content_top_leads=[...tracked].sort((a,b)=>Number(b.n_leads||0)-Number(a.n_leads||0)).slice(0,5);
  const content_top_cvr=[...tracked].filter(r=>Number(r.n_leads||0)>=cfg.limits.weekly_min_content_leads && r.conversion_rate!==null).sort((a,b)=>Number(b.conversion_rate||0)-Number(a.conversion_rate||0)||Number(b.n_leads||0)-Number(a.n_leads||0)).slice(0,5);
  const ranked=[...courses]; const strongest=[...ranked].sort((a,b)=>Number(b.won_this_week||0)-Number(a.won_this_week||0)||Number(b.conversion_rate_this_week??-1)-Number(a.conversion_rate_this_week??-1)||Number(b.leads_this_week||0)-Number(a.leads_this_week||0))[0]||null;
  const weakest=[...ranked].sort((a,b)=>Number(a.won_this_week||0)-Number(b.won_this_week||0)||Number(a.conversion_rate_this_week??999)-Number(b.conversion_rate_this_week??999)||Number(a.lead_delta_pct??999)-Number(b.lead_delta_pct??999))[0]||null;
  const unmapped_total=healthRows.reduce((s,r)=>s+Number(r.n||0),0);
  payload={...payload,weekly_performance:courses,strongest_course:strongest,weakest_course:weakest,content_top_leads,content_top_cvr,utm_weekly:content,warnings,data_health:{unmapped_total,show_alert:unmapped_total>=cfg.thresholds.unmapped_alert_min,rows:healthRows}};
} else {
  const q0=rows('Q0 Data Health'); const q5raw=rows('Q5 Warning Scan'); const q5=q5raw.filter(r=>countFlags(r)>0).sort((a,b)=>countFlags(b)-countFlags(a)).slice(0,cfg.limits.max_warning_rows); const unmapped_total=q0.reduce((s,r)=>s+Number(r.n||0),0);
  payload={...payload,kpi:$('Q1 KPI').first()?.json||{},breakdown:rows('Q2 Breakdown'),utm_daily:rows('Q3 UTM Daily'),no_lead_courses:rows('Q4 No-Lead Courses'),warnings:q5,focus_group:rows('Q6 Focus Group'),data_health:{unmapped_total,show_alert:unmapped_total>=cfg.thresholds.unmapped_alert_min,rows:q0}};
}
return [{json:payload}];

function clean(v,lang){ let s=String(v||'').trim(); const fence=String.fromCharCode(96).repeat(3); if(s.startsWith(fence)){ s=s.slice(3).replace(new RegExp('^'+(lang||'json'),'i'),'').trim(); } if(s.endsWith(fence)) s=s.slice(0,-3).trim(); return s; } function parse(v){ if(typeof v==='object')return v; return JSON.parse(clean(v,'json')); }
let parsed; try{ parsed=parse($json.output||$json.text||$json); }catch(e){ return [{json:{state:{iteration:1,max_loops:3,invalid_streak:0,history:[]},hypothesis:'Không đọc được output SQL Writer',sql:'',sql_valid:false,guardrail_reason:'JSON không hợp lệ: '+e.message}}]; }
let sql=clean(parsed.sql||'','sql').replace(/;\s*$/,''); const reasons=[];
if(!/^(SELECT|WITH)\b/i.test(sql)) reasons.push('Query phải bắt đầu bằng SELECT hoặc WITH');
if(/\b(INSERT|UPDATE|DELETE|DROP|CREATE|MERGE|ALTER|TRUNCATE|CALL|EXECUTE|GRANT|REVOKE)\b/i.test(sql)) reasons.push('Có từ khóa ghi/xóa bị cấm');
if(sql.includes(';')) reasons.push('Không cho phép nhiều statement');
if(/SELECT\s+\*/i.test(sql)) reasons.push('Không cho phép SELECT *');
const lm=sql.match(/\bLIMIT\s+(\d+)\b/i); if(!lm) reasons.push('Thiếu LIMIT'); else if(Number(lm[1])>200) reasons.push('LIMIT vượt 200');
const tick=String.fromCharCode(96); const parts=sql.split(tick); const refs=parts.filter((_,i)=>i%2===1); if(refs.some(r=>!r.startsWith('tmdatabase.dm_base_crm.')&&r!=='tmdatabase.dm_daily_brief.dim_course')) reasons.push('Tham chiếu bảng ngoài allowlist');
return [{json:{state:parsed.state||{},hypothesis:parsed.hypothesis||'',rationale:parsed.rationale||'',sql,sql_valid:reasons.length===0,guardrail_reason:reasons.join('; ')}}];

